const themeToggle = document.getElementById('themeToggle');
const starsEl = document.getElementById('stars');

function generateStars() {
  const count = 200;
  let circles = '';
  for (let i = 0; i < count; i++) {
    const x = Math.random() * 100;
    const y = Math.random() * 100;
    const r = Math.random() * 1.5 + 0.3;
    const o = Math.random() * 0.7 + 0.3;
    circles += `<circle cx="${x}%" cy="${y}%" r="${r}" fill="rgba(255,255,255,${o})"/>`;
  }
  starsEl.innerHTML = `<svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">${circles}</svg>`;
}
generateStars();

function setTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  themeToggle.textContent = theme === 'day' ? '☀️' : '🌙';
  themeToggle.title = theme === 'day' ? 'Switch to Night Mode' : 'Switch to Day Mode';
  localStorage.setItem('sky-theme', theme);
}

